function B($h){New-Object Drawing.SolidBrush ([Drawing.ColorTranslator]::FromHtml($h))}
function PX($h,$w){$p=New-Object Drawing.Pen ([Drawing.ColorTranslator]::FromHtml($h)),$w;$p.StartCap='Round';$p.EndCap='Round';$p}
function F($n,$s,$st='Regular'){try{New-Object Drawing.Font($n,$s,[Drawing.FontStyle]::$st,[Drawing.GraphicsUnit]::Pixel)}catch{New-Object Drawing.Font('Yu Gothic UI',$s,[Drawing.FontStyle]::$st,[Drawing.GraphicsUnit]::Pixel)}}
function RR($g,$x,$y,$w,$h,$r,$b,$p=$null){$path=New-Object Drawing.Drawing2D.GraphicsPath;$d=$r*2;$path.AddArc($x,$y,$d,$d,180,90);$path.AddArc($x+$w-$d,$y,$d,$d,270,90);$path.AddArc($x+$w-$d,$y+$h-$d,$d,$d,0,90);$path.AddArc($x,$y+$h-$d,$d,$d,90,90);$path.CloseFigure();if($b){$g.FillPath($b,$path)};if($p){$g.DrawPath($p,$path)};$path.Dispose()}
function T($g,$t,$f,$b,$x,$y,$w,$h,$a='Center'){$sf=New-Object Drawing.StringFormat;$sf.Alignment=[Drawing.StringAlignment]::$a;$sf.LineAlignment='Center';$sf.Trimming='EllipsisCharacter';$g.DrawString($t,$f,$b,(New-Object Drawing.RectangleF $x,$y,$w,$h),$sf);$sf.Dispose()}
function I($g,$path,$x,$y,$w,$h,$rot=0){$im=[Drawing.Image]::FromFile($path);$sc=[Math]::Min($w/$im.Width,$h/$im.Height);$dw=$im.Width*$sc;$dh=$im.Height*$sc;$s=$g.Save();$g.TranslateTransform($x+$w/2,$y+$h/2);if($rot){$g.RotateTransform($rot)};$g.DrawImage($im,-$dw/2,-$dh/2,$dw,$dh);$g.Restore($s);$im.Dispose()}
function Header($g){T $g 'ビューティムード診断' $Title (B '#e94d7a') 80 35 920 74;T $g '3つの美容軸を、3問で見る簡易診断' $Sub (B '#3c2929') 130 108 820 34}
function Foot($g){RR $g 115 1415 850 45 22 (B '#fffdfb') (PX '#f29ab4' 2);T $g '答えをつなげて、あなたのビューティムードへ' $Small (B '#e94d7a') 130 1418 820 38}
function C($g,$x,$y,$w,$h,$kana,$lab,$c,$fill){RR $g $x $y $w $h 24 (B $fill) (PX $c 3);T $g $kana $Kana (B $c) ($x+8) ($y+4) 68 ($h-8);T $g $lab $Label (B $c) ($x+78) ($y+6) ($w-88) ($h-12) 'Near'}
function Q($g,$x,$y,$w,$h,$q,$txt,$c){RR $g $x $y $w $h 24 (B '#fffefa') (PX $c 3);T $g $q $QF (B $c) $x ($y+2) $w 32;T $g $txt $Tiny (B '#3c2929') ($x+8) ($y+34) ($w-16) ($h-38)}
